  const types = [...new Set(brands.map(brand => brand.type))].sort((a, b) => a.localeCompare(b, "es"));
  const classes = [...new Set(brands.flatMap(brandClassNumbers))].sort((a, b) => a - b);
  const change = (key: keyof BrandFilterValues, value: string) => { onFilters({ ...filters, [key]: value }); setStatusMenu(null); };
  const clear = () => { onFilters({ ...EMPTY_BRAND_FILTERS }); onFilter("Todas"); onQuery(""); setStatusMenu(null); };
